import React from 'react';
import Header from './Header';
import Footer from './Footer';

// Component layout chung cho toàn bộ ứng dụng
function AppLayout({ children }) {
  return (
    <>
      <Header />
      <main>
        {children} {/* Đây là nơi các Page Component sẽ được hiển thị */}
      </main>
      
      {/* Contact Bar - Đưa vào đây hoặc trong Footer tùy theo thiết kế */}
      <div className="contact">
          <div className="container">
              <div className="inner-wrap">
                  <div className="register-1">
                      <img src="/assets/images/img-1.svg" alt="icon" />
                      <div><a href="#">Đăng ký nhận tin</a></div>
                  </div>
                  <form className="form-register">
                      <input type="text" placeholder="Nhập email của bạn..." />
                      <button>Đăng Ký</button>
                  </form>
                  <div className="register-2">
                      <img src="/assets/images/img-2.svg" alt="icon" />
                      <div><a href="tel:0973285886">Hỗ trợ/Mua hàng</a></div>
                  </div>
                  <div className="register-3">097 328 58 86</div>
              </div>
          </div>
      </div>
      {/* End Contact */}
      
      <Footer />
    </>
  );
}

export default AppLayout;
